const projects=[{id:'erp',title:'Modular ERP',category:'BUSINESS SOFTWARE',status:'In development',summary:'A modular ERP for inventory, accounting and reporting.',tech:['C# / .NET','MSSQL','OOP'],description:'An ERP project I’m developing to bring inventory, accounting and reporting workflows together in a modular application.',features:['Inventory and stock workflows in one application','Accounting and reporting workflows','Modular development with C#/.NET and object-oriented programming'],note:'In development. The card shows a concept interface, not a screenshot of the application.',art:`<div class="ui-preview"><div class="ui-top"><i></i><i></i><i></i><span>ERP</span></div><div class="erp-body"><div class="ui-side"><i></i><i></i><i></i><i></i><i></i></div><div class="ui-main"><h4>Operations overview</h4><div class="mini-stats"><div>INVENTORY<b>Stock</b></div><div>FINANCE<b>Accounts</b></div><div>ANALYTICS<b>Reports</b></div></div><div class="bars">${[30,50,38,65,45,80,65,95].map(h=>`<i style="height:${h}%"></i>`).join('')}</div></div></div></div>`},{id:'ai',title:'Home automation assistant',category:'AI & AUTOMATION',status:'In development',summary:'A personal assistant for voice and device control.',tech:['AI','Arduino','NFC'],description:'A personal AI and home automation assistant designed to bring voice, camera and device control into a central dashboard.',features:['Designing voice interaction and camera features','A central dashboard for device control','NFC and Arduino-based home automation'],note:'In design and development. The visual is a concept illustration of the planned interface.',art:`<div class="assistant-ui"><div class="wave">${[15,26,40,55,30,65,42,58,25,45,60,34,50,22,14].map((h,i)=>`<i style="height:${h}px;--i:${i}"></i>`).join('')}</div><p>Personal home automation assistant</p><div class="device-row"><span>VOICE</span><span>CAMERA</span><span>DEVICES</span></div></div>`},{id:'cv',title:'AI CV Maker',category:'FULL STACK & AI',status:'Built',summary:'A CV builder made with Next.js and FastAPI.',tech:['Next.js','FastAPI','PostgreSQL'],description:'An AI-assisted CV builder with a Next.js interface, FastAPI services and a PostgreSQL database.',features:['AI-assisted CV creation','Web interface built with Next.js','API and data layer built with FastAPI and PostgreSQL'],note:'The card shows a concept interface, not a live application screenshot.',art:`<div class="cv-screen"><div class="cv-controls"><strong>CV Maker</strong><i></i><i></i><i></i><span>Create with AI ↗</span></div><div class="cv-page"><b></b>${Array(16).fill('<i></i>').join('')}</div></div>`}];
projects.unshift({id:'os',title:'SNAKE OS',category:'SYSTEM DEVELOPMENT',status:'In development',summary:'A mobile operating system I’m building from scratch.',tech:['Operating system','Mobile','Independent project'],description:'SNAKE OS is my personal mobile operating system, built from scratch. I’m developing it independently, and work is ongoing.',features:['Building a mobile operating system from scratch','An independent personal systems project'],note:'In development. The visual is a concept, not a screenshot of a running system.',art:`<div class="os-concept"><strong>SNAKE OS.</strong><span class="os-subtitle">A MOBILE OS, BUILT FROM SCRATCH.</span><div class="os-layers"><span>SYSTEM</span><i></i><span>MOBILE</span><i></i><span>INTERFACE</span></div></div>`});
projects.push({id:'stock',title:'Warehouse inventory',category:'DEPO & INVENTORY',status:'Built',summary:'An inventory application built with C# and MSSQL.',tech:['C#','MSSQL'],description:'A warehouse inventory application I developed using C# and MSSQL, with a SQL-backed data layer for stock records.',features:['An application focused on warehouse inventory','Application development in C#','MSSQL database integration'],note:'The card shows a concept interface for the project.',art:`<div class="stock-concept"><div class="stock-title">WAREHOUSE / STOCK</div><div class="stock-head"><span>APPLICATION</span><b>C#</b></div><div class="stock-connect">↓</div><div class="stock-head"><span>DATABASE</span><b>MSSQL</b></div></div>`});
document.querySelector('#project-grid').innerHTML=projects.map((p,i)=>`<button class="project-card" data-project="${p.id}" aria-haspopup="dialog" aria-label="${p.title} project details"><div class="project-art ${p.id}-art"><span class="art-status">${p.status}</span><div aria-hidden="true">${p.art}</div></div><div class="project-meta"><h3>${p.title}</h3><span aria-hidden="true">↗</span></div><p>${p.summary}</p><div class="tags">${p.tech.map(t=>`<span>${t}</span>`).join('')}</div></button>`).join('');
const dialog=document.querySelector('#project-dialog');let opener;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{opener=button;const p=projects.find(p=>p.id===button.dataset.project);document.querySelector('#dialog-content').innerHTML=`<span class="dialog-kicker">${p.category} · ${p.status}</span><h2 id="dialog-title">${p.title}</h2><p>${p.description}</p><h3>About this project</h3><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><div class="tags">${p.tech.map(t=>`<span>${t}</span>`).join('')}</div><p class="detail-note">${p.note}</p><a class="button primary" href="mailto:yilanciserkan30@gmail.com?subject=${encodeURIComponent(p.title+' enquiry')}">Ask me about this project ↗</a>`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();document.body.style.overflow='hidden'}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus()});
document.querySelector('#copy-email').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('yilanciserkan30@gmail.com');status.textContent='Email address copied.'}catch{status.textContent='Could not copy. Email: yilanciserkan30@gmail.com'}setTimeout(()=>status.textContent='',5000)});
document.querySelector('#year').textContent=new Date().getFullYear();
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-heading,.project-card,.about-grid,.capabilities article,.timeline article,.contact h2').forEach((e,i)=>{e.classList.add('reveal');observer.observe(e)})}
let ticking=false;const progress=document.querySelector('.scroll-progress');window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{const total=document.documentElement.scrollHeight-innerHeight;progress.style.width=`${total>0?scrollY/total*100:0}%`;ticking=false});ticking=true}},{passive:true});
